    /*
     * Assign a CarrierService
     * 
     * @param	parentId	UUID
     * @param	assignment 	CarrierService 
     * @return	ShippingMethod
     */
    public ShippingMethod assignCarrierService( UUID parentId, CarrierService assignment ) {
	    LOGGER.info("assigning CarrierService as " + assignment.toString() );

	    ShippingMethod parentEntity = repository.findById( parentId ).get();
	    assignment = registry.project( CarrierService.class, assignment.getCarrierServiceId());

	    // ------------------------------------------
		// assign the CarrierService to the parent entity
		// ------------------------------------------ 
	    parentEntity.setCarrierService( assignment );

	    // ------------------------------------------
    	// save the parent entity
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

	/*
	 * Unassign the CarrierService
	 * 
	 * @param	parentId		UUID
	 * @return	ShippingMethod
	 */
	public ShippingMethod unAssignCarrierService( UUID parentId ) {
		ShippingMethod parentEntity = repository.findById(parentId).get();

		LOGGER.info("unAssigning CarrierService on " + parentEntity.toString() );
		
	    // ------------------------------------------
		// null out the CarrierService on the parent entithy
		// ------------------------------------------     
	    parentEntity.setCarrierService(null);

	    // ------------------------------------------
		// save the parent entity
		// ------------------------------------------ 
	    repository.save(parentEntity);
    
	    return parentEntity;
	}


    /*
     * Add to the Channels
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	ShippingMethod
     */
    public ShippingMethod addToChannels( UUID parentId, Channel addTo ) {
	    LOGGER.info("handling AssignChannelsToShippingMethodEvent - " );
	    
	    ShippingMethod parentEntity = repository.findById(parentId).get();
	    Channel child = registry.project( Channel.class, addTo.getChannelId());
	    
	    parentEntity.getChannels().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the Channels
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	ShippingMethod
     */
	public ShippingMethod removeFromChannels( UUID parentId, Channel removeFrom ) {
	    LOGGER.info("handling RemoveChannelsFromShippingMethodEvent " );
	
	    ShippingMethod parentEntity = repository.findById(parentId).get();
	    Channel child = registry.project( Channel.class, removeFrom.getChannelId());
	    
	    parentEntity.getChannels().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}



